using System;using Exoduser.UnityPort.Core;class Program{static int fail,pass;static void Check(bool value,string name){if(value)pass++;else{fail++;Console.WriteLine("FAIL "+name);}}static int Main(){foreach(bool start in new[]{false,true}){var policy=new FrontendPadPolicy();int f=0;var world=(FrontendPadPhase)3;var held=new FrontendPadFrame{Number=++f,CancelHeld=!start,StartHeld=start};Check(!policy.Step(world,held,true).Hold,"held entering world must release");policy.Step(world,new FrontendPadFrame{Number=++f},true);held.Number=++f;Check(policy.Step(world,held,true).Hold,"world "+(start?"Start":"B")+" hold reaches skip");held.Number=++f;policy.Step(world,held,false);held.Number=++f;Check(!policy.Step(world,held,true).Hold,"blur requires release");policy.Step(world,new FrontendPadFrame{Number=++f},true);held.Number=++f;Check(policy.Step(world,held,true).Hold,"world rearmed hold after focus");Check(!policy.Step(world,held,true).Hold,"same frame consumed once");}Console.WriteLine(pass+" passed "+fail+" failed");return fail==0?0:2;}}